<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;class Signalement extends Model{protected $fillable=['user_id','coupure_electrique_id','quartier_id','titre','description','adresse','latitude','longitude','statut','date_signalement'];protected function casts():array{return ['date_signalement'=>'datetime'];}public function user():BelongsTo{return $this->belongsTo(User::class);}public function quartier():BelongsTo{return $this->belongsTo(Quartier::class);}public function coupureElectrique():BelongsTo{return $this->belongsTo(CoupureElectrique::class);}}
